-- Lista de matéria-prima do Wik cadastrada como INSUMO, e a coluna que diz
-- se a unidade foi confirmada por gente ou inferida por regra.
--
-- Pedido da dona do projeto em 10/09/2026: "cadastre todos esses insumos com
-- o valor atualizado lá no módulo de produção".
--
-- ---------------------------------------------------------------------------
-- De onde vêm os dados
-- ---------------------------------------------------------------------------
-- Relatório "LISTA DE MAT.PRIMA" do Wik Sistemas, empresa HEBRON - DINAMICA
-- MATRIZ, emitido em 10/09/2026, 12 páginas, **503 itens** — e são 503 linhas
-- aqui embaixo, conferidas contra o "Total de Itens: 503" impresso no rodapé
-- do próprio relatório.
--
-- O relatório traz REFERENCIA, DESCRIÇÃO, PREÇO, COLEÇÃO, FORNECEDOR,
-- COD.FORNECEDOR, DATA CADASTRO e SALDO. Do que ele traz, entram aqui:
-- referência (como `codigo`), descrição (como `nome`), preço (como
-- `custo_atual`), coleção (como `especificacao`) e fornecedor (vinculado
-- **só por nome exato**, ver abaixo).
--
-- ---------------------------------------------------------------------------
-- O que o relatório NÃO traz, e o que foi feito com isso
-- ---------------------------------------------------------------------------
-- 1. UNIDADE. O Wik não imprime a unidade de medida. E sem unidade o preço
--    não quer dizer nada: R$ 45,00 pode ser o metro de um tecido plano ou o
--    quilo de uma malha — e o custo da peça muda por um fator de três
--    conforme a escolha.
--
--    A unidade aqui foi definida por regra automática
--    (`server/src/lib/insumoUnidade.js`), e cada insumo carrega em
--    `observacoes` a frase que explica POR QUE ficou naquela unidade.
--    A coluna nova `unidade_confianca` guarda o quanto se pode confiar nisso:
--
--      'alta'  (368 itens) — a descrição diz a unidade ou a família é
--                            inequívoca: "POR QUILO", MALHA, SUPLEX, TECIDO,
--                            TRICOLINE, BOTÃO, ETIQUETA, CADARÇO… ou o
--                            cadastro de origem informa LARGURA, que só
--                            existe em artigo vendido por metro.
--      'media' ( 25 itens) — a família sugere, mas não prova (retilínea,
--                            fio 30, kit, referência começando por TEC).
--      'baixa' (110 itens) — PALPITE. Nome próprio de artigo sem
--                            palavra-chave (ATRIA, MISSY, KOLON) e toda a
--                            entretela, que ora vem em rolo (metro) ora
--                            cortada (peça).
--
--    NULL em `unidade_confianca` quer dizer unidade posta por gente — é o
--    caso de todos os insumos que já existiam antes desta migration, e passa
--    a ser o caso de qualquer um que alguém confirmar na tela.
--
--    Isto é a REGRA 2 aplicada: o sistema não finge que sabe. A aba de
--    Insumos da Produção mostra os 135 de confiança média/baixa numa fila de
--    conferência, e **nenhum insumo com unidade não confirmada é usado para
--    redistribuir custo de produto sem aviso na tela**.
--
-- 2. SALDO em estoque. O relatório traz saldo, e ele NÃO é lançado aqui.
--    Entrada de estoque neste sistema é por nota fiscal ou por inventário,
--    com movimento rastreável — criar saldo direto no cadastro seria estoque
--    que apareceu do nada. O saldo que o Wik informava está escrito em
--    `observacoes`, para quem for fazer o inventário ter o número à mão.
--
-- 3. FORNECEDOR. Vinculado só quando o nome do relatório bate EXATAMENTE
--    (ignorando caixa e espaço) com um fornecedor já cadastrado. Nome
--    parecido não vincula (REGRA 2) — fica nulo e alguém decide na tela.
--
-- 4. CUSTO AUSENTE. 26 dos 503 itens ficam sem custo: 22 vêm com a coluna
--    PREÇO em branco no relatório, e outros 4 vêm com R$ 0,000000 impresso.
--    Os dois casos entram com `custo_atual` NULO — nunca R$ 0,00. Matéria-
--    prima de graça não existe; zero ali é cadastro sem preço no Wik, e
--    deixar zero entrar no cálculo faria a peça parecer mais barata do que é.
--    "Sem custo" e "custo zero" são coisas diferentes, e a tela escreve qual
--    é.
--
-- 5. CÓDIGO REPETIDO. A coluna REFERENCIA do relatório vem TRUNCADA em ~14
--    caracteres, e por isso 9 referências aparecem repetidas apontando para
--    artigos diferentes ("TECIDO PIQUET" quatro vezes). Como `insumos.codigo`
--    é UNIQUE, as repetições receberam sufixo " (2)", " (3)"… e a observação
--    registra o caso, para quem for conferir no Wik saber que o código de lá
--    está cortado.
--
-- ---------------------------------------------------------------------------
-- O que esta migration NÃO faz
-- ---------------------------------------------------------------------------
-- ⚠️ NÃO altera o motor de cálculo (REGRA 1). Nada aqui toca em
--    `materiais.valor_unitario`, em `custos_industriais` ou em preço.
--    O custo de nenhum produto muda por causa desta migration.
--
-- ⚠️ NÃO liga insumo a ficha técnica. O vínculo é decisão humana, feito na
--    aba de Insumos da Produção, com casamento exato e fila de conferência.
--
-- ⚠️ NÃO apaga nem sobrescreve insumo já cadastrado às cegas: quando o
--    código já existe, o custo só é atualizado se o custo de lá NÃO tiver
--    vindo de nota fiscal (nota vale mais que lista impressa), e a unidade
--    só é mexida se ninguém tiver confirmado a unidade de lá.
--
-- Autorização de esquema (REGRA 4): uma coluna nova, aditiva e nula por
-- padrão (`insumos.unidade_confianca`). Nenhuma tabela nova, nenhuma coluna
-- removida, nenhum comportamento existente alterado.

-- ---------------------------------------------------------------------------
-- 1. A coluna que separa "unidade que alguém confirmou" de "unidade que o
--    sistema chutou". Sem ela, o palpite viraria fato em silêncio.
-- ---------------------------------------------------------------------------
ALTER TABLE insumos ADD COLUMN IF NOT EXISTS unidade_confianca VARCHAR(20);

COMMENT ON COLUMN insumos.unidade_confianca IS
  'NULL = unidade posta/confirmada por gente. alta|media|baixa = unidade inferida por regra automática (server/src/lib/insumoUnidade.js); a frase que explica a regra fica em observacoes.';

CREATE INDEX IF NOT EXISTS idx_insumos_unidade_confianca
  ON insumos(unidade_confianca) WHERE unidade_confianca IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 2. A lista, em tabela temporária, para poder separar "atualiza" de "cria"
--    e registrar histórico de custo dos dois jeitos.
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE _lista_wik (
  codigo         VARCHAR(60),
  nome           VARCHAR(200),
  tipo           VARCHAR(30),
  unidade        VARCHAR(20),
  confianca      VARCHAR(20),
  especificacao  TEXT,
  fornecedor_nome TEXT,
  custo          NUMERIC(14,6),
  observacoes    TEXT
) ON COMMIT DROP;


-- Confere na hora: se o número não for 503, alguma linha se perdeu na
-- geração e é melhor a migration falhar do que cadastrar meia lista.
DO $$
DECLARE n INTEGER;
BEGIN
  SELECT COUNT(*) INTO n FROM _lista_wik;
  IF n <> 503 THEN
    RAISE EXCEPTION 'Lista do Wik veio com % itens, e o relatório de 10/09/2026 tem 503. Migration abortada.', n;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- 3. Histórico de custo dos que JÁ EXISTEM e vão mudar de custo.
--    Gravado ANTES do UPDATE, senão o custo anterior se perde.
-- ---------------------------------------------------------------------------
SELECT i.id, i.custo_atual, l.custo, 'manual', now()
  FROM insumos i
  JOIN _lista_wik l ON l.codigo = i.codigo
 WHERE l.custo IS NOT NULL
   AND i.custo_origem IS DISTINCT FROM 'nota'
   AND i.custo_atual IS DISTINCT FROM l.custo;

-- ---------------------------------------------------------------------------
-- 4. Atualiza os que já existem.
--    · custo só entra se o de lá não veio de nota fiscal;
--    · unidade e tipo só entram se ninguém tiver confirmado a unidade de lá
--      (unidade_confianca IS NOT NULL significa "ainda é palpite do sistema");
--    · nome e especificação nunca são sobrescritos — quem cadastrou pode ter
--      corrigido, e a lista do Wik não é mais confiável que a correção.
-- ---------------------------------------------------------------------------
UPDATE insumos i
   SET custo_atual = CASE
         WHEN l.custo IS NOT NULL AND i.custo_origem IS DISTINCT FROM 'nota' THEN l.custo
         ELSE i.custo_atual END,
       custo_origem = CASE
         WHEN l.custo IS NOT NULL AND i.custo_origem IS DISTINCT FROM 'nota' THEN 'manual'
         ELSE i.custo_origem END,
       custo_atualizado_em = CASE
         WHEN l.custo IS NOT NULL AND i.custo_origem IS DISTINCT FROM 'nota' THEN now()
         ELSE i.custo_atualizado_em END,
       unidade = CASE
         WHEN i.unidade_confianca IS NOT NULL OR i.unidade IS NULL THEN l.unidade
         ELSE i.unidade END,
       unidade_confianca = CASE
         WHEN i.unidade_confianca IS NOT NULL OR i.unidade IS NULL THEN l.confianca
         ELSE i.unidade_confianca END,
       tipo = CASE
         WHEN i.tipo = 'outro' THEN l.tipo
         ELSE i.tipo END,
       observacoes = COALESCE(NULLIF(i.observacoes, ''), '') ||
         CASE WHEN COALESCE(i.observacoes, '') = '' THEN '' ELSE E'\n' END || l.observacoes,
       atualizado_em = now()
  FROM _lista_wik l
 WHERE l.codigo = i.codigo;

-- ---------------------------------------------------------------------------
-- 5. Cria os que ainda não existem.
--    O fornecedor entra só com nome EXATO (REGRA 2): parecido não conta.
-- ---------------------------------------------------------------------------
                     fornecedor_id, custo_atual, custo_origem, custo_atualizado_em,
                     observacoes, ativo)
SELECT l.codigo, l.nome, l.tipo, l.unidade, l.confianca, l.especificacao,
       (SELECT f.id FROM fornecedores f
         WHERE upper(btrim(f.nome)) = upper(btrim(l.fornecedor_nome))
         ORDER BY f.id LIMIT 1),
       l.custo,
       CASE WHEN l.custo IS NULL THEN NULL ELSE 'manual' END,
       CASE WHEN l.custo IS NULL THEN NULL ELSE now() END,
       l.observacoes, TRUE
  FROM _lista_wik l
 WHERE NOT EXISTS (SELECT 1 FROM insumos i WHERE i.codigo = l.codigo);

-- ---------------------------------------------------------------------------
-- 6. Histórico de custo dos recém-criados. Sem isto, o primeiro custo de um
--    insumo não teria data nem origem, e o gráfico de "de quanto pra quanto
--    subiu" começaria do nada.
-- ---------------------------------------------------------------------------
SELECT i.id, NULL, i.custo_atual, 'manual', now()
  FROM insumos i
  JOIN _lista_wik l ON l.codigo = i.codigo
 WHERE i.custo_atual IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM insumo_custo_historico h WHERE h.insumo_id = i.id);
